package com.ynxweb4.shop;
import static org.junit.Assert.*;
import org.junit.Test;import org.json.JSONObject;import java.time.Instant;import java.util.HashMap;
public final class PayHandoffRecoveryTest {
 static final String A="ynx1"+"q".repeat(38),B="ynx1"+"p".repeat(38);
 static class Memory implements PayHandoffRecovery.Storage {final HashMap<String,String> data=new HashMap<>();public String get(String key){return data.getOrDefault(key,"");}public void put(String key,String value){data.put(key,value);}}
 static ProductSession session(String actor)throws Exception{return ProductSession.parse(new JSONObject().put("account",actor).put("token","original-product-service-test-token").put("expiresAt",Instant.now().plusSeconds(240).toString()).toString(),Instant.now());}
 static JSONObject order(String actor)throws Exception{return new JSONObject().put("ID","ord_original").put("Buyer",actor).put("StoreID","store_original").put("TotalYNXT",8L).put("Currency","YNXT");}
 static JSONObject receipt(JSONObject order)throws Exception{return new JSONObject().put("order",new JSONObject(order.toString()).put("InvoiceID","inv_original")).put("invoiceId","inv_original").put("deepLink","ynxpay://invoice/inv_original");}
 @Test public void unknownHandoffKeepsOriginalOpaqueKeyAcrossRestartAndCallerMutation()throws Exception{Memory m=new Memory();JSONObject order=order(A);PayHandoffRecovery.Prepared first=PayHandoffRecovery.prepare(m,session(A),order);order.put("TotalYNXT",99);PayHandoffRecovery.Prepared next=PayHandoffRecovery.prepare(m,session(A),order(A));assertEquals(first.key,next.key);assertEquals(8L,first.order.getLong("TotalYNXT"));assertEquals(first.body().toString(),next.body().toString());String saved=m.get(first.namespace);assertFalse(saved.contains(A));assertFalse(saved.contains("ord_original"));assertEquals(2,new JSONObject(saved).length());}
 @Test public void anotherActorCannotPrepareOriginalOrderOrUseItsPendingKey()throws Exception{Memory m=new Memory();PayHandoffRecovery.Prepared own=PayHandoffRecovery.prepare(m,session(A),order(A));assertThrows(SecurityException.class,()->PayHandoffRecovery.prepare(m,session(B),order(A)));PayHandoffRecovery.Prepared other=PayHandoffRecovery.prepare(m,session(B),order(B));assertNotEquals(own.namespace,other.namespace);assertNotEquals(own.key,other.key);}
 @Test public void changedOrderCannotRotateUnknownHandoff()throws Exception{Memory m=new Memory();PayHandoffRecovery.Prepared own=PayHandoffRecovery.prepare(m,session(A),order(A));String before=m.get(own.namespace);assertThrows(IllegalStateException.class,()->PayHandoffRecovery.prepare(m,session(A),order(A).put("TotalYNXT",9)));assertEquals(before,m.get(own.namespace));}
 @Test public void exactReceiptClearsOnlyOriginalIntentAndReturnsExactReviewLink()throws Exception{Memory m=new Memory();PayHandoffRecovery.Prepared own=PayHandoffRecovery.prepare(m,session(A),order(A)),other=PayHandoffRecovery.prepare(m,session(B),order(B));assertEquals("ynxpay://invoice/inv_original",PayHandoffRecovery.confirmed(m,own,receipt(order(A))));assertEquals("",m.get(own.namespace));assertFalse(m.get(other.namespace).isEmpty());}
 @Test public void mismatchedActorAmountInvoiceOrRedirectPreservesOriginalIntent()throws Exception{for(int i=0;i<5;i++){Memory m=new Memory();PayHandoffRecovery.Prepared own=PayHandoffRecovery.prepare(m,session(A),order(A));String before=m.get(own.namespace);JSONObject response=receipt(order(A));if(i==0)response.getJSONObject("order").put("Buyer",B);if(i==1)response.getJSONObject("order").put("TotalYNXT",9);if(i==2)response.put("invoiceId","inv_other");if(i==3)response.put("deepLink","https://foreign.invalid/invoice/inv_original");if(i==4)response.put("deepLink","ynxpay://invoice/inv_original?execute=true");assertThrows(Exception.class,()->PayHandoffRecovery.confirmed(m,own,response));assertEquals(before,m.get(own.namespace));}}
 @Test public void malformedStorageAndWriteFailureNeverLoseOriginalEvidence()throws Exception{Memory m=new Memory();PayHandoffRecovery.Prepared own=PayHandoffRecovery.prepare(m,session(A),order(A));m.put(own.namespace,"broken");assertThrows(Exception.class,()->PayHandoffRecovery.prepare(m,session(A),order(A)));assertEquals("broken",m.get(own.namespace));Memory failing=new Memory(){public void put(String key,String value){throw new IllegalStateException("storage unavailable");}};assertThrows(Exception.class,()->PayHandoffRecovery.prepare(failing,session(A),order(A)));assertTrue(failing.data.isEmpty());}
 @Test public void fractionalAndOverflowAmountsCannotMatchAnOriginalIntegerOrder()throws Exception{Memory m=new Memory();assertThrows(Exception.class,()->PayHandoffRecovery.prepare(m,session(A),order(A).put("TotalYNXT",8.5)));assertThrows(Exception.class,()->PayHandoffRecovery.prepare(m,session(A),order(A).put("TotalYNXT",new java.math.BigInteger("9223372036854775808"))));assertTrue(m.data.isEmpty());}
}
